head.b:skin:
:root{--bg:#0c0b0d;--accent:#e0bd95;--text:#ede7e0;--line:#ffffff24}
body{margin:0;background:var(--bg);color:var(--text);font-family:Arial,'Noto Sans KR',sans-serif;line-height:1.85}
a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}
.rev-nav{display:flex;justify-content:space-between;align-items:center;padding:22px max(24px,calc((100vw - 1100px)/2));border-bottom:1px solid var(--line);gap:25px}
.rev-logo{font-size:26px;color:#fff!important;letter-spacing:.25em;font-weight:700}
.rev-navlinks{display:flex;gap:28px}.rev-navlinks a{font-size:13px;color:#eee}
.rev-hero{padding:100px 24px 95px;text-align:center;background:radial-gradient(ellipse at center,#423121,#0c0b0d 70%);border-bottom:1px solid var(--line)}
.rev-hero h1{font-family:Georgia,serif;font-weight:400;font-size:clamp(44px,6vw,80px);line-height:1.1;margin:10px 0 25px}
